SELECT id, name, description, category_id, longitude, latitude, address, creator_id, status, created_at, updated_at
FROM place
WHERE status = 1
  AND latitude BETWEEN #{minLat} AND #{maxLat}
  AND longitude BETWEEN #{minLng} AND #{maxLng}

SELECT id, name, description, category_id, longitude, latitude, address, creator_id, status, created_at, updated_at
FROM place
WHERE status = 1
  AND latitude BETWEEN #{minLat} AND #{maxLat}
  AND longitude BETWEEN #{minLng} AND #{maxLng}
ORDER BY id DESC
LIMIT #{limit}

SELECT COUNT(DISTINCT user_id) FROM (
    SELECT creator_id AS user_id FROM place WHERE id = #{placeId}
    UNION
    SELECT user_id FROM post WHERE place_id = #{placeId} AND status = 1
) t
